const o=[{id:"nedycha",group:"A",tile:"Nedýcha",title:"Nedýcha, nereaguje",sub:"oživovanie",img:"/prva-pomoc/nedycha-kpr.webp",imgCap:"stláčanie hrudníka, záchranca pri chrbte",fotky:[{src:"/prva-pomoc/commons-forthood-dalmatin-na-boku-kpr.webp",cap:"KPR na boku (US Army, PD)"},{src:"/prva-pomoc/dvids9092345-malinois-na-boku-dlane-na-hrudniku.webp",cap:"dlane na hrudníku (US Army, PD)"}],spoznas:["nereaguje na meno ani dotyk","hrudník sa nehýbe","necítiš tep na ľavom boku za lakťom"],kroky:["Zavolaj naňho a zatras ním. Ak sa bráni alebo dýcha, oživovanie nerob.","Otvor papuľu, vytiahni jazyk, pozri do hrdla. Čo vidíš, vyber.","Polož ho na bok na tvrdú zem.","Stláčaj hrudník: rýchlo, 2 stlačenia za sekundu, do tretiny hĺbky hrudníka. Vždy ho nechaj vrátiť.","Po 30 stlačeniach zavri papuľu, natiahni krk a 2× mu vdýchni do nosa, kým sa zdvihne hrudník.","Opakuj 30 : 2. Každé 2 minúty na pár sekúnd skontroluj dych. Ak ste dvaja, striedajte sa.","Pokračuj aj cestou k veterinárovi."],extra:[{h:"Kam dať ruky",items:["Stredný a veľký pes s guľatým hrudníkom (labrador): obe dlane na najširšie miesto hrudníka.","Úzky hlboký hrudník (chrt, doberman): obe dlane nad srdce, tam, kde sa hrudníka dotkne lakeť.","Malý pes do 10 kg: jedna ruka obopne hrudník, stláčaš palcom oproti prstom.","Buldog, mops: na boku, dlane na najširšie miesto."]}],nikdy:["nestláčaj psa, ktorému bije srdce","neprerušuj stláčanie na viac než 10 sekúnd"],bezSignalu:"oživovanie len kupuje čas na cestu. Úprimne: prežije málo psov (5 až 7 zo 100 aj na klinike). Ak je pomoc ďaleko a nič sa nemení, smieš prestať."},{id:"dusi",group:"A",tile:"Dusí sa",title:"Dusí sa",img:"/prva-pomoc/dusi-heimlich.webp",imgCap:"päsť hneď za posledné rebrá",spoznas:["panika, škrabe si papuľu","nevie sa nadýchnuť, je ticho","ďasná modrajú"],lead:["Ak kašle, vzduch prechádza. Nechaj ho kašľať a choď k veterinárovi."],kroky:["Otvor papuľu a pozri sa. Čo vidíš, vyber pinzetou alebo kliešťami. Nie prstami.","Nejde to: postav sa za psa, päsť pod rebrá, 5 prudkých stlačení dovnútra a nahor. Malého psa drž chrbtom k sebe.","Stále nič: zdvihni mu zadok, hlava dole, 5 úderov dlaňou medzi lopatky. Opakuj.","Stratil vedomie: teraz už vyber prstami, čo je v hrdle.","Loptička v hrdle a pes v bezvedomí: polož ho na chrbát, natiahni krk, palcami zvonku pod sánkou tlač loptičku smerom k papuli.","Nedýcha: pokračuj kartou NEDÝCHA.","Aj keď predmet vyšiel, choď k veterinárovi. Hrdlo môže opuchnúť."],nikdy:["prsty do papule psa pri vedomí","nehmataj naslepo","žiadny náhubok"],bezSignalu:"celý kruh opakuj sám, kým predmet nevyjde."},{id:"krvaca",group:"A",tile:"Silne krváca",title:"Silne krváca",img:"/prva-pomoc/krvaca-tlak.webp",imgCap:"tlak priamo na ranu, celou dlaňou",posledne:{img:"/prva-pomoc/krvaca-skrtidlo.webp",h:"Až keď nič iné nepomáha: škrtidlo",t:"široký pás látky NAD ranou, pevne uviazať. Zapíš si čas a už ho nepovoľuj."},fotky:[{src:"/prva-pomoc/dvids9049537-tlak-dlanami-cez-gazu-figurina.webp",cap:"tlak dlaňami cez gázu (US Air Force, PD)"},{src:"/prva-pomoc/commons-tccc-obvaz-prednej-nohy-figurina.webp",cap:"tlakový obväz nohy (US Army, PD)"}],spoznas:["krv strieka alebo rýchlo tečie","bledé ďasná, rýchly dych, studené labky = šok"],kroky:["Pritlač na ranu čistú látku (tričko, šatka) a drž. Silno, celou dlaňou.","Nohu zdvihni nad úroveň srdca, ak sa dá.","Obviaž pevne cez látku.","Presiaklo to? Nedávaj nič dole. Pridaj ďalšiu vrstvu a tlač ďalej.","Choď k veterinárovi, tlak drž celú cestu."],extra:[{h:"Zapichnutý predmet (konár, sklo)",t:"nevyťahuj. Obviaž okolo neho."},{h:"Pazúr, ucho, labka",t:"krvácajú veľa, vyzerajú horšie, než sú. Tlač 5 až 10 minút bez pozerania. Ak neprestane do 15 minút, pohotovosť."}],nikdy:["nepozeraj pod obväz, či to prestalo","žiadny peroxid ani alkohol do rany"],bezSignalu:"škrtidlo je posledná možnosť, len na nohu alebo chvost, keď tlak nezaberá. Použi široký elastický obväz, zapíš si čas a už ho nepovoľuj."},{id:"brucho",group:"A",tile:"Nafúknuté brucho",title:"Nafúknuté brucho, dáví naprázdno",img:"/prva-pomoc/brucho-nafuknute.webp",imgCap:"nafúknutý žalúdok tlačí na rebrá",sub:"otočenie žalúdka",spoznas:["chce vracať a nič nevyjde","brucho tvrdé ako bubon","nevie si ľahnúť, slintá","najmä veľké psy s hlbokým hrudníkom"],kroky:["Hneď do auta k NAJBLIŽŠIEMU veterinárovi. Zavolaj mu cestou.","Nedávaj nič jesť ani piť.","Skolabuje: karta NEDÝCHA."],extra:[{h:"Doma sa nedá urobiť nič.",t:"Bez operácie pes zomrie, po 6 hodinách šance rýchlo klesajú.",warn:!0}],nikdy:["nečakaj, či to prejde","žiadne kvapky proti nafukovaniu","nič neprepichuj"]},{id:"krce",group:"A",tile:"Záchvat",title:"Záchvat, kŕče",img:"/prva-pomoc/krce-cas.webp",imgCap:"nedrž ho, meraj čas",spoznas:["spadne, stuhne, „pádluje“ nohami, slintá, môže sa pomočiť","potom je zmätený"],vet:{h:"Hneď k veterinárovi, ak",items:["záchvat trvá viac než 2 minúty (volaj)","viac než 5 minút (ide o život)","druhý záchvat v ten istý deň","neprebral sa","je to jeho prvý záchvat (ozvi sa v ten deň)"]},kroky:["Pozri na hodinky. Meraj čas.","Odprac všetko, o čo sa môže udrieť. Nedrž ho.","Ticho, tieň. Neprikrývaj ho, prehrieva sa.","Ak sa dá, natoč video pre veterinára.","Po záchvate: pokoj, voda, pozor na schody a svah. Môže byť zmätený až deň."],nikdy:["ruky do papule (jazyk neprehltne, ale pohryzie ťa)","nedrž ho, nekrop vodou","nič mu nedávaj do úst","neprenášaj ho počas záchvatu"],bezSignalu:"počkaj, kým záchvat skončí, potom ho nes. V horúčave mu vlaž brucho a slabiny."},{id:"prehriatie",group:"B",tile:"Prehriatie",title:"Prehriatie",img:"/prva-pomoc/prehriatie.webp",imgCap:"voda na hruď, brucho a stehná, hlava suchá",fotky:[{src:"/prva-pomoc/pes-vo-vode.webp",cap:"zdravý pes vo vode (CC BY-SA, Chris Light)"}],spoznas:["silno dychčí a neprestáva","slintá, vracia, potáca sa","v najhoršom kŕče a kolaps"],kroky:["Stoj. Tieň.","Chlaď HNEĎ, najstudenejšou vodou, akú máš (potok, fľaša, hadica). Najprv chladiť, až potom cestovať.","Zdravého psa pri vedomí ponor do vody po krk. Hlava vždy nad vodou.","Starého, chorého, krátkonosého alebo apatického psa neponáraj. Polievaj ho a ovievaj.","Lej na hruď, brucho a vnútorné stehná. Hlava a papuľa ostávajú suché.","Daj mu piť po dúškoch.","Prestaň, keď sa dych upokojí. Potom k veterinárovi, aj keď vyzerá dobre."],nikdy:["nečakaj s chladením na veterinára","neprikrývaj ho mokrým uterákom (pod neho áno)","nenúť ho ísť pešo"],bezSignalu:"chladenie JE liečba. Chlaď v potoku, potom ho pomaly nes."},{id:"had",group:"B",tile:"Had",title:"Uštipol ho had",sub:"vretenica",img:"/prva-pomoc/had-nesenie.webp",imgCap:"malého psa nes, nech nechodí",fotky:[{src:"/prva-pomoc/vlastna-opuch-prednej-nohy-po-vretenici-1.webp",cap:"opuch nohy po vretenici"},{src:"/prva-pomoc/vretenica-samica-pieniny.webp",cap:"vretenica (CC BY-SA, Charles J. Sharp)",znak:"zle"},{src:"/prva-pomoc/uzovka-hlava-zlte-skvrny.webp",cap:"užovka (PD, G. Chernilevsky)",znak:"ok"}],porovnanie:{img:"/prva-pomoc/vretenica-vs-uzovka.webp",h:"Vretenica alebo užovka?",l:"Jedovatá",r:"Neškodná",t:"Vretenica: cikcak na chrbte, zvislá zrenička. Užovka: žlté polmesiace za hlavou, okrúhla zrenička. Aj tak hada nechytaj."},spoznas:["náhla bolesť a rýchly tmavý opuch, často na papuli alebo nohe","niekedy dve bodky","slabosť, potácanie"],kroky:["Pokoj. Hada nechytaj, stačí fotka z diaľky.","Psa upokoj a nenechaj ho behať. Pohyb rozháňa jed.","Malého psa nes. K veľkému priveď auto, alebo choď pomaly s prestávkami.","Zavolaj veterinárovi, že idete.","Choď hneď, aj keď opuch nevidíš. Príznaky prídu do hodiny."],nikdy:["škrtidlo ani obväz","nevysávaj, nerež","žiadny ľad","žiadne lieky"],bezSignalu:"jediná prvá pomoc je pokoj a rýchly, pokojný presun."},{id:"hmyz",group:"B",tile:"Hmyz",title:"Bodol ho hmyz",img:"/prva-pomoc/hmyz-zihadlo.webp",imgCap:"žihadlo zoškrabni do boku, nestláčaj",fotky:[{src:"/prva-pomoc/osa-vespula.webp",cap:"osa (CC BY-SA, Soebe)"}],spoznas:["kňučí, líže si miesto, malý opuch"],vet:{h:"Hneď k veterinárovi, ak",items:["opúcha papuľa, hlava alebo krk","dýcha ťažko, píska","vracia alebo má hnačku","slabne, kolabuje","bodnutie je v papuli alebo hrdle","bodnutí je veľa"]},kroky:["Žihadlo vyber hneď, čímkoľvek (necht, karta, pinzeta). Rozhoduje rýchlosť. Nestláčaj vačok.","Prilož studený obklad cez látku, 10 minút.","Sleduj ho aspoň pol hodiny, potom ešte zvyšok dňa."],nikdy:["ľudské lieky na alergiu bez pokynu veterinára. Niektoré obsahujú látky, ktoré psa otrávia."],bezSignalu:"ak chodíš ďaleko od ciest, vypýtaj si vopred od svojho veterinára liek a dávku pre svojho psa."},{id:"jed",group:"B",tile:"Jed",title:"Zjedol jed",img:"/prva-pomoc/jed-vybrat.webp",imgCap:"úchop za špicákmi, vyber spredu, odfoť obal",dalsi:[{img:"/prva-pomoc/jed-panel.webp",h:"Vždy nebezpečné"}],spoznas:["vracia, slintá, trasie sa, potáca","niekedy nič, príznaky prídu o hodiny až dni"],kroky:["Zober mu to. Vyprázdni papuľu, ak sa dá bezpečne.","Zisti čo, koľko a kedy. Odfoť obal alebo zober vzorku.","Volaj veterinára HNEĎ. Nečakaj na príznaky.","Choď, aj keď vyzerá zdravo."],extra:[{h:"Vždy nebezpečné",items:["čokoláda (čím tmavšia, tým horšie)","sladidlo xylitol (žuvačky)","hrozno a hrozienka","jed na potkany a slimáky","nemrznúca zmes","ľudské lieky (ibuprofén, paracetamol)","huby","zelená voda so sinicami"],pills:!0},{h:"Sinice",t:"opláchni ho čistou vodou a nedovoľ mu olizovať srsť."}],nikdy:["nevyvolávaj vracanie, pokiaľ ti to veterinár výslovne nepovie.","žiadna slaná voda","žiadne mlieko ani živočíšne uhlie namiesto veterinára"],bezSignalu:"nestrácaj čas domácimi receptami. Choď k signálu a k autu."},{id:"kliest",group:"B",tile:"Kliešť",title:"Kliešť",img:"/prva-pomoc/kliest-pinzeta.webp",imgCap:"pinzetou tesne pri koži, rovno hore",fotky:[{src:"/prva-pomoc/ixodes-ricinus-samica-samec.webp",cap:"kliešť obyčajný (CC BY-SA, Alan R Walker)"}],vet:{h:"Hneď k veterinárovi, ak",pre:"3 týždne sleduj.",items:["je apatický, nežerie, má horúčku","moč je tmavý alebo červený","žltnú mu ďasná alebo oči"],post:"Na Slovensku je to často babezióza a ide o dni."},kroky:["Vyber ho hneď, nečakaj domov.","Chyť ho tesne pri koži.","Pinzetou ťahaj rovno a pomaly. Háčikom na kliešte otáčaj.","Nestláčaj mu telo.","Miesto umy. Zapíš si dátum.","Prezri celého psa: hlava, uši, podpazušie, medzi prstami, slabiny."],nikdy:["olej, alkohol, lak ani oheň na kliešťa"]},{id:"podchladenie",group:"B",tile:"Podchladenie",title:"Podchladenie",img:"/prva-pomoc/podchladenie.webp",imgCap:"izolácia pod psa, zabaliť, teplá fľaša pri hrudi",fotky:[{src:"/prva-pomoc/pes-zabaleny-v-deke.webp",cap:"pes zabalený v deke (CC0)"}],spoznas:["trasie sa, je stuhnutý, spomalený","keď sa triasť prestane a slabne, je to horšie, nie lepšie"],kroky:["Závetrie, sucho. Daj dole mokrý postroj.","Osuš ho a polož na niečo, čo izoluje (karimatka, ruksak).","Zabaľ ho, aj zospodu. Pritlač si ho k telu.","Fľašu s teplou vodou zabaľ do látky a daj mu ju k hrudníku a bruchu.","Ak pije, daj vlažnú vodu.","K veterinárovi, aj keď sa preberie."],extra:[{h:"Omrzliny (uši, chvost, labky sú bledé, tvrdé)",t:"netrieť. Ohrievať až tam, kde už znovu nezamrznú, teplou vodou, v ktorej udržíš ruku."}],nikdy:["horúca voda, fén, trenie snehom","teplý predmet priamo na kožu"]},{id:"topil",group:"B",tile:"Topil sa",title:"Topil sa",img:"/prva-pomoc/topil-bok.webp",imgCap:"na boku, hlava nižšie, vyčisti papuľu",fotky:[{src:"/prva-pomoc/03-commons-figurina-na-boku-plaz.webp",cap:"záchranárska figurína na boku (CC0)"},{src:"/prva-pomoc/04-flickr-stena-zabalene-v-uteraku.webp",cap:"zabalený v uteráku (CC BY-SA, Clevergrrl)"}],kroky:["Na ľad za ním nechoď.","Polož ho na bok, hlavu nižšie než telo, vyčisti papuľu. Len pár sekúnd.","Nedýcha: karta NEDÝCHA, začni vdychmi.","Osuš ho a zabaľ.","K veterinárovi, aj keď vyzerá dobre."],extra:[{h:"Potom 2 dni sleduj dych.",t:"Kašeľ, rýchle alebo ťažké dýchanie = hneď k veterinárovi.",warn:!0},{h:"Pozor aj na",t:"veľa vypitej vody pri aportovaní z vody a morskú vodu. Potácanie, vracanie, nafúknuté brucho = veterinár."}],nikdy:["nestláčaj mu brucho, aby „vyšla voda“","nedrž ho dlho dole hlavou"]},{id:"zlomenina",group:"C",tile:"Zlomenina",title:"Zlomenina, nedostúpi na nohu",img:"/prva-pomoc/zlomenina-maly.webp",imgCap:"malého nes, zranená noha voľne",fotky:[{src:"/prva-pomoc/mwd-nosidla-dvaja-nosici-2025.webp",cap:"nosidlá (US Air Force, PD)"}],dalsi:[{img:"/prva-pomoc/zlomenina-deka.webp",h:"Veľký pes",t:"na bundu alebo deku, napnúť ako nosidlá, nesú dvaja."}],spoznas:["nohu drží hore, visí v divnom uhle, opúcha","pri chrbtici ťahá zadné nohy"],kroky:["Pozor, aj tvoj pes ťa od bolesti môže pohrýzť. Pozri kartu NÁHUBOK.","Nohu nenaprávaj a nedlahuj.","Otvorenú ranu len prekry čistou látkou.","Nenechaj ho chodiť. Malého nes v náručí, zranená noha voľne, nič ju netlačí. Veľkého presuň na bundu alebo deku a neste dvaja.","Podozrenie na chrbticu: len na niečom pevnom a rovnom (doska, karimatka), bez ohýbania.","K veterinárovi hneď."],nikdy:["ľudské lieky proti bolesti. Ibuprofén a paracetamol psa otrávia."],bezSignalu:"ak musí ísť sám, tak pomaly a po troch. Nohu pod lakťom alebo kolenom môžeš zľahka obložiť zrolovanou karimatkou. Stehno a rameno nikdy."},{id:"labka",group:"C",tile:"Labka",title:"Poranená labka",img:"/prva-pomoc/labka-obvaz.webp",imgCap:"obväz od prstov nahor, dva prsty pod obväz",vet:{h:"Hneď k veterinárovi, ak",items:["krváca aj po 15 minútach","rana je hlboká alebo v nej niečo ostalo","je odtrhnutý pazúr","popálil si labky (horúci asfalt: chlaď chladnou vodou 10 až 20 minút)"]},kroky:["Opláchni čistou vodou. Sklo alebo tŕň vyber, len ak ide ľahko. Hlboké nechaj.","Tlač čistou látkou 5 až 10 minút.","Obviaž: gáza na ranu, kúsok vaty medzi prsty, obväz od prstov nahor. Pod obväz musia vojsť dva prsty.","Vonku naň natiahni vrecko alebo ponožku, doma daj dole.","Nenechaj ho obväz hrýzť."],extra:[{h:"Osina medzi prstami",t:"vytiahni len to, čo jasne trčí. Opuch medzi prstami = veterinár, osina putuje hlbšie."}]},{id:"pohryzol",group:"C",tile:"Pohryzenie",title:"Pohryzol ho pes alebo diviak",img:"/prva-pomoc/pohryzenie-hrudnik.webp",imgCap:"rana na hrudníku: fólia a dlaň",fotky:[{src:"/prva-pomoc/k9-tccc-osetrenie-simulator-2026.webp",cap:"obväzovanie psa, simulátor (US Army, PD)"}],vet:{h:"K veterinárovi",items:["hrudník, brucho, krk, hlava = hneď","Všetko ostatné v ten istý deň, najlepšie do 6 hodín"]},lead:["Malá dierka klame. Zuby trhajú pod kožou. Pes môže vyzerať v poriadku a skolabovať o hodinu."],kroky:["Silné krvácanie: karta KRVÁCA.","Malú ranu vypláchni čistou vodou.","Rana na hrudníku, z ktorej to syčí alebo bublá: prekry ju fóliou alebo vreckom a pritlač. Ak sa dych zhorší, okraj nadvihni.","Vyhreznuté črevá netlač späť. Prekry vlhkou čistou látkou.","Zabaľ ho, nech nechodí, a choď."],extra:[{h:"Líška alebo iné divé zviera",t:"zavolaj veterinára kvôli besnote a maj pri sebe očkovací preukaz."}],nikdy:["peroxid do rany","nič nezašívaj ani nelep"]},{id:"popalenina",group:"C",tile:"Popálenina",title:"Popálenina",img:"/prva-pomoc/popalenina-chladenie.webp",imgCap:"chladná voda len na popálené miesto",kroky:["Elektrina: najprv vypni prúd, až potom sa psa dotkni.","Chlaď chladnou tečúcou vodou 20 minút. Malého psa chlaď len na mieste a zvyšok drž v teple. Vodu nie na papuľu.","Chemikália: zmývaj veľkým množstvom vody.","Voľne prekry potravinovou fóliou alebo čistou vlhkou látkou.","K veterinárovi vždy. Po prehryznutom kábli aj vtedy, keď vyzerá dobre."],nikdy:["ľad","masť, maslo, krém","neprepichuj pľuzgiere"]},{id:"oko",group:"C",tile:"Oko",title:"Poranené oko",img:"/prva-pomoc/oko-vyplach.webp",imgCap:"slabý prúd od vnútorného kútika",kroky:["Chemikália: vyplachuj hneď a dlho, 15 až 20 minút. Čím máš: fyziologický roztok, inak čistá voda. Slabým prúdom, nie do papule.","Nenechaj ho škrabať si oko.","Zapichnutý predmet nevyberaj.","Vypadnuté oko (krátkonosé psy): nezatláčaj. Prekry mokrou čistou látkou, stále vlhči a choď hneď.","K veterinárovi v ten istý deň, aj keď len žmúri."],nikdy:["netlač na oko","žiadne ľudské kvapky"]},{id:"vracia",group:"C",tile:"Vracia",title:"Vracia, má hnačku",img:"/prva-pomoc/vracia-koza.webp",imgCap:"koža medzi lopatkami, má hneď klesnúť",fotky:[{src:"/prva-pomoc/02-usmc-dasna-tlak-palcom.webp",cap:"kontrola ďasien (USMC, PD)"},{src:"/prva-pomoc/04-usmc-voda-po-troche-z-dlani.webp",cap:"voda po troche (USMC, PD)"}],vet:{h:"Hneď k veterinárovi, ak",items:["krv vo zvratkoch alebo stolici","dávi naprázdno a má nafúknuté brucho (karta NAFÚKNUTÉ BRUCHO)","vracia opakovane viac než 4 až 6 hodín","je apatický","je to šteňa alebo starý pes"]},lead:["Stačí sledovať: raz vracal, inak je čulý. Dávaj vodu po troche a nechaj ho oddychovať."],extra:[{h:"Je odvodnený?",t:"Zdvihni kožu medzi lopatkami. Ak sa vracia pomaly a ďasná sú suché a lepkavé, potrebuje veterinára. U vráskavých a starých psov sa radšej pozri na ďasná."}],nikdy:["ľudské lieky"]},{id:"nahubok",group:"D",tile:"Náhubok",title:"Náhubok z obväzu alebo vodítka",img:"/prva-pomoc/nahubok-fazy.webp",imgCap:"slučka zhora, kríženie pod bradou, mašľa za ušami",fotky:[{src:"/prva-pomoc/mwd-improvizovany-nahubok-z-gazy.webp",cap:"náhubok z gázy (US Army, PD)"}],kroky:["Urob slučku, zhora ju nasaď na papuľu a utiahni.","Prekríž konce pod bradou.","Zaviaž na mašľu za ušami, aby sa dal hneď stiahnuť."],extra:[{h:"Nie, ak",items:["vracia","dýcha ťažko","dusí sa","má krátky nos","má poranenú tvár alebo hrudník","je v bezvedomí","je prehriaty"],after:"Krátkonosého psa radšej zabaľ do deky.",warn:!0}]},{id:"poriadok",group:"D",tile:"Je v poriadku?",title:"Je v poriadku?",sub:"životné funkcie",img:"/prva-pomoc/dasna-tlak.webp",imgCap:"zatlač na ružové ďasno nad tesákom",dalsi:[{img:"/prva-pomoc/tep-stehno.webp",h:"Tep vnútri stehna",t:"bruškami ukazováka a prostredníka, vysoko pri slabine."}],fotky:[{src:"/prva-pomoc/B1-dvids-femoralny-pulz-stojaci-pes.webp",cap:"tep na stehne (US Air Force, PD)"},{src:"/prva-pomoc/B2-dvids-femoralny-pulz-zozadu.webp",cap:"tep na stehne zozadu (US Army, PD)"}],fakty:[{h:"Ďasná",t:"ružové a vlhké. Bledé = krvácanie, šok. Modré = dusí sa. Tehlovočervené = prehriatie. Žlté = pečeň, krv."},{h:"Zatlač na ďasno",t:"ružová sa má vrátiť do 2 sekúnd. Pri tmavých ďasnách tlač na ružové miesto."},{h:"Dych v pokoji",t:"10 až 35 za minútu."},{h:"Tep (ľavý bok za lakťom alebo vnútro stehna)",t:"hmataj ukazovákom a prostredníkom, nie palcom. Veľký pes 60 až 100, malý 90 až 140."},{h:"Teplota",t:"37,5 až 39,2 °C."}]},{id:"niest",group:"D",tile:"Ako ho niesť",title:"Ako ho niesť",img:"/prva-pomoc/zlomenina-maly.webp",imgCap:"malého v náručí, hrudník a zadok",dalsi:[{img:"/prva-pomoc/zlomenina-deka.webp",h:"Veľký",t:"deku napni ako nosidlá, nesú dvaja."},{img:"/prva-pomoc/niest-doska.webp",h:"Chrbtica",t:"pevná doska, podlož krk a boky, pripútaj, dvíhajte naraz."}],fotky:[{src:"/prva-pomoc/mwd-pes-na-nosidlach-2025.webp",cap:"pes na nosidlách (US Air Force, PD)"},{src:"/prva-pomoc/dvids-psia-figurina-na-boku-dvihaju-nosidla.webp",cap:"dvaja dvíhajú naraz (US Navy, PD)"}],fakty:[{h:"Malý",t:"v náručí, podopri hrudník a zadok."},{h:"Veľký",t:"na bunde alebo deke, dvaja."},{h:"Chrbtica",t:"len na pevnom."}]},{id:"lekarnicka",group:"D",tile:"Lekárnička",title:"Lekárnička do ruksaku",img:"/prva-pomoc/lekarnicka.webp",imgCap:"10 vecí do ruksaku",fotky:[{src:"/prva-pomoc/lekarnicka-pre-psa-box.webp",cap:"lekárnička pre psa (CC BY-SA, Elgaard)"},{src:"/prva-pomoc/commons-hacik-na-klieste-otom.webp",cap:"háčik na kliešte (CC BY-SA, Otom)"}],zoznam:["Gáza a obväz","samolepiaci obväz","páska","rukavice","nožnice s tupou špičkou","pinzeta a háčik na kliešte","fyziologický roztok","záchranná fólia","náhradné vodítko (náhubok aj nosidlá)","číslo na veterinára a pohotovosť"],extra:[{h:"K tomu po dohode s veterinárom",t:"liek na alergiu s dávkou pre tvojho psa."},{h:"Do lekárničky nepatrí",t:"peroxid, živočíšne uhlie, škrtidlo, masti."}]}],t=[[/kartou NEDÝCHA|karta NEDÝCHA/g,"nedycha"],[/karta KRVÁCA/g,"krvaca"],[/kartu NÁHUBOK/g,"nahubok"],[/karta NAFÚKNUTÉ BRUCHO/g,"brucho"]],n=[{id:"nedycha",group:"A",tile:"Not breathing",title:"Not breathing, not responding",sub:"resuscitation",img:"/prva-pomoc/nedycha-kpr.webp",imgCap:"chest compressions, rescuer at the back",fotky:[{src:"/prva-pomoc/commons-forthood-dalmatin-na-boku-kpr.webp",cap:"CPR on the side (US Army, PD)"},{src:"/prva-pomoc/dvids9092345-malinois-na-boku-dlane-na-hrudniku.webp",cap:"hands on the chest (US Army, PD)"}],spoznas:["does not react to name or touch","the chest does not move","no heartbeat on the left side behind the elbow"],kroky:["Call him and shake him. If he resists or breathes, do not resuscitate.","Open the mouth, pull the tongue out, look into the throat. Remove what you see.","Lay him on his side on hard ground.","Compress the chest: fast, 2 compressions per second, a third of the chest depth. Always let it come back up.","After 30 compressions close the mouth, stretch the neck and breathe into the nose 2×, until the chest rises.","Repeat 30 : 2. Every 2 minutes check breathing for a few seconds. If you are two, take turns.","Keep going on the way to the vet."],extra:[{h:"Where to put your hands",items:["Medium and large dog with a round chest (labrador): both palms on the widest part of the chest.","Narrow deep chest (greyhound, doberman): both palms over the heart, where the elbow touches the chest.","Small dog under 10 kg: one hand wraps around the chest, press with the thumb against the fingers.","Bulldog, pug: on the side, palms on the widest part."]}],nikdy:["do not compress a dog whose heart is beating","do not stop compressions for more than 10 seconds"],bezSignalu:"resuscitation only buys time to get help. Honestly: few dogs survive (5 to 7 in 100, even in a clinic). If help is far away and nothing changes, you may stop."},{id:"dusi",group:"A",tile:"Choking",title:"Choking",img:"/prva-pomoc/dusi-heimlich.webp",imgCap:"fist just behind the last ribs",spoznas:["panic, pawing at the mouth","cannot breathe in, is silent","gums turn blue"],lead:["If he coughs, air is getting through. Let him cough and go to the vet."],kroky:["Open the mouth and look. Remove what you see with tweezers or pliers. Not with fingers.","Does not work: stand behind the dog, fist under the ribs, 5 sharp thrusts inward and upward. Hold a small dog with his back to you.","Still nothing: lift his hindquarters, head down, 5 blows with the palm between the shoulder blades. Repeat.","He lost consciousness: now remove what is in the throat with your fingers.","A ball in the throat and the dog unconscious: lay him on his back, stretch the neck, with your thumbs from outside under the jaw push the ball toward the mouth.","Not breathing: continue with card NOT BREATHING.","Even if the object came out, go to the vet. The throat can swell."],nikdy:["fingers in the mouth of a conscious dog","do not feel around blindly","no muzzle"],bezSignalu:"repeat the whole cycle on your own until the object comes out."},{id:"krvaca",group:"A",tile:"Heavy bleeding",title:"Heavy bleeding",img:"/prva-pomoc/krvaca-tlak.webp",imgCap:"pressure right on the wound, with the whole palm",fotky:[{src:"/prva-pomoc/dvids9049537-tlak-dlanami-cez-gazu-figurina.webp",cap:"palms pressing through gauze (US Air Force, PD)"},{src:"/prva-pomoc/commons-tccc-obvaz-prednej-nohy-figurina.webp",cap:"pressure bandage on a leg (US Army, PD)"}],spoznas:["blood spurts or flows fast","pale gums, fast breathing, cold paws = shock"],kroky:["Press a clean cloth (t-shirt, scarf) on the wound and hold. Hard, with the whole palm.","Raise the leg above the level of the heart, if you can.","Bandage firmly over the cloth.","Soaked through? Do not take anything off. Add another layer and keep pressing.","Go to the vet, keep the pressure the whole way."],posledne:{img:"/prva-pomoc/krvaca-skrtidlo.webp",h:"Only when nothing else works: tourniquet",t:"a wide strip of cloth ABOVE the wound, tied tight. Note the time and never loosen it."},extra:[{h:"Object stuck in the wound (branch, glass)",t:"do not pull it out. Bandage around it."},{h:"Claw, ear, paw",t:"bleed a lot and look worse than they are. Press 5 to 10 minutes without looking. If it does not stop within 15 minutes, emergency vet."}],nikdy:["do not look under the bandage to see if it stopped","no peroxide or alcohol in the wound"],bezSignalu:"a tourniquet is the last option, only on a leg or the tail, when pressure does not work. Use a wide elastic bandage, note the time and never loosen it."},{id:"brucho",group:"A",tile:"Bloated belly",title:"Bloated belly, retching with nothing coming up",sub:"twisted stomach",img:"/prva-pomoc/brucho-nafuknute.webp",imgCap:"the bloated stomach presses on the ribs",spoznas:["tries to vomit and nothing comes up","belly hard as a drum","cannot lie down, drools","mostly large dogs with a deep chest"],kroky:["Straight into the car to the NEAREST vet. Call on the way.","Give nothing to eat or drink.","He collapses: card NOT BREATHING."],extra:[{h:"Nothing can be done at home.",t:"Without surgery the dog dies; after 6 hours the chances drop fast.",warn:!0}],nikdy:["do not wait to see if it passes","no anti-bloating drops","do not puncture anything"]},{id:"krce",group:"A",tile:"Seizure",title:"Seizure, fit",img:"/prva-pomoc/krce-cas.webp",imgCap:"do not hold him, time it",vet:{h:"Straight to the vet if",items:["the seizure lasts more than 2 minutes (call)","more than 5 minutes (life at risk)","a second seizure on the same day","he did not come round","it is his first seizure (call the same day)"]},spoznas:['falls, goes stiff, "paddles" with the legs, drools, may wet himself',"confused afterwards"],kroky:["Look at your watch. Time it.","Clear away anything he could hit. Do not hold him.","Quiet, shade. Do not cover him, he overheats.","If you can, film it for the vet.","After the seizure: calm, water, watch out for stairs and slopes. He may be confused for up to a day."],nikdy:["hands in the mouth (he will not swallow the tongue, but he will bite you)","do not hold him, do not splash him with water","put nothing in his mouth","do not carry him during the seizure"],bezSignalu:"wait until the seizure ends, then carry him. In the heat, wet his belly and groin."},{id:"prehriatie",group:"B",tile:"Overheating",title:"Overheating",img:"/prva-pomoc/prehriatie.webp",imgCap:"water on chest, belly and thighs, head dry",fotky:[{src:"/prva-pomoc/pes-vo-vode.webp",cap:"healthy dog in water (CC BY-SA, Chris Light)"}],spoznas:["pants hard and does not stop","drools, vomits, staggers","at worst seizures and collapse"],kroky:["Stop. Shade.","Cool him NOW, with the coldest water you have (stream, bottle, hose). Cool first, travel after.","A healthy, conscious dog: put him in the water up to the neck. Head always above water.","Do not put an old, sick, flat-faced or listless dog in the water. Pour water over him and fan him.","Pour on the chest, belly and inner thighs. Head and muzzle stay dry.","Let him drink in sips.","Stop when the breathing calms down. Then to the vet, even if he looks fine."],nikdy:["do not wait for the vet to start cooling","do not cover him with a wet towel (under him is fine)","do not make him walk"],bezSignalu:"cooling IS the treatment. Cool him in a stream, then carry him slowly."},{id:"had",group:"B",tile:"Snake",title:"Snake bite",sub:"adder",img:"/prva-pomoc/had-nesenie.webp",imgCap:"carry a small dog, do not let him walk",fotky:[{src:"/prva-pomoc/vlastna-opuch-prednej-nohy-po-vretenici-1.webp",cap:"leg swelling after an adder bite"},{src:"/prva-pomoc/vretenica-samica-pieniny.webp",cap:"adder (CC BY-SA, Charles J. Sharp)",znak:"zle"},{src:"/prva-pomoc/uzovka-hlava-zlte-skvrny.webp",cap:"grass snake (PD, G. Chernilevsky)",znak:"ok"}],porovnanie:{img:"/prva-pomoc/vretenica-vs-uzovka.webp",h:"Adder or grass snake?",l:"Venomous",r:"Harmless",t:"Adder: zigzag on the back, vertical pupil. Grass snake: yellow crescents behind the head, round pupil. Do not catch the snake either way."},spoznas:["sudden pain and fast dark swelling, often on the muzzle or a leg","sometimes two dots","weakness, staggering"],kroky:["Stay calm. Do not catch the snake, a photo from a distance is enough.","Calm the dog and do not let him run. Movement spreads the venom.","Carry a small dog. Bring the car to a large one, or walk slowly with breaks.","Call the vet that you are coming.","Go now, even if you do not see swelling. Symptoms come within an hour."],nikdy:["no tourniquet or bandage","do not suck, do not cut","no ice","no medicines"],bezSignalu:"the only first aid is calm and a fast, calm trip to the vet."},{id:"hmyz",group:"B",tile:"Insect sting",title:"Stung by an insect",img:"/prva-pomoc/hmyz-zihadlo.webp",imgCap:"scrape the sting out sideways, do not squeeze",fotky:[{src:"/prva-pomoc/osa-vespula.webp",cap:"wasp (CC BY-SA, Soebe)"}],vet:{h:"Straight to the vet if",items:["the muzzle, head or neck swells","breathes heavily, wheezes","vomits or has diarrhoea","gets weak, collapses","the sting is in the mouth or throat","there are many stings"]},spoznas:["whines, licks the spot, small swelling"],kroky:["Remove the sting at once, with anything (fingernail, card, tweezers). Speed matters. Do not squeeze the venom sac.","Apply a cold compress over a cloth, 10 minutes.","Watch him at least half an hour, then for the rest of the day."],nikdy:["human allergy medicine without the vet saying so. Some contain substances that poison dogs."],bezSignalu:"if you hike far from roads, ask your vet in advance for a medicine and a dose for your dog."},{id:"jed",group:"B",tile:"Poison",title:"Ate something poisonous",img:"/prva-pomoc/jed-vybrat.webp",imgCap:"grip behind the canines, take it out from the front, photograph the package",dalsi:[{img:"/prva-pomoc/jed-panel.webp",h:"Always dangerous"}],spoznas:["vomits, drools, trembles, staggers","sometimes nothing, symptoms come after hours or days"],kroky:["Take it away from him. Empty the mouth, if it is safe.","Find out what, how much and when. Photograph the package or keep a sample.","Call the vet NOW. Do not wait for symptoms.","Go, even if he looks healthy."],extra:[{h:"Always dangerous",items:["chocolate (the darker, the worse)","sweetener xylitol (chewing gum)","grapes and raisins","rat and slug poison","antifreeze","human medicines (ibuprofen, paracetamol)","mushrooms","green water with blue-green algae"],pills:!0},{h:"Blue-green algae",t:"rinse him with clean water and do not let him lick his coat."}],nikdy:["do not make him vomit unless the vet clearly tells you to.","no salt water","no milk or activated charcoal instead of the vet"],bezSignalu:"do not waste time on home remedies. Head for signal and the car."},{id:"kliest",group:"B",tile:"Tick",title:"Tick",img:"/prva-pomoc/kliest-pinzeta.webp",imgCap:"tweezers close to the skin, straight up",fotky:[{src:"/prva-pomoc/ixodes-ricinus-samica-samec.webp",cap:"castor bean tick (CC BY-SA, Alan R Walker)"}],vet:{h:"Straight to the vet if",pre:"Watch for 3 weeks.",items:["is listless, does not eat, has a fever","urine is dark or red","gums or eyes turn yellow"],post:"In Slovakia it is often babesiosis and it is a matter of days."},kroky:["Remove it right away, do not wait until you are home.","Grab it close to the skin.","With tweezers pull straight and slowly. With a tick hook, twist.","Do not squeeze its body.","Wash the spot. Note the date.","Check the whole dog: head, ears, armpits, between the toes, groin."],nikdy:["oil, alcohol, nail polish or fire on the tick"]},{id:"podchladenie",group:"B",tile:"Hypothermia",title:"Hypothermia",img:"/prva-pomoc/podchladenie.webp",imgCap:"insulation under the dog, wrap him, warm bottle at the chest",fotky:[{src:"/prva-pomoc/pes-zabaleny-v-deke.webp",cap:"dog wrapped in a blanket (CC0)"}],spoznas:["shivers, is stiff, slow","when he stops shivering and gets weaker, it is worse, not better"],kroky:["Shelter from the wind, somewhere dry. Take off a wet harness.","Dry him and lay him on something that insulates (sleeping mat, backpack).","Wrap him, underneath too. Hold him against your body.","Wrap a bottle of warm water in cloth and put it at his chest and belly.","If he drinks, give lukewarm water.","To the vet, even if he comes round."],extra:[{h:"Frostbite (ears, tail, paws are pale and hard)",t:"do not rub. Warm them only where they will not freeze again, with water warm enough to keep your hand in."}],nikdy:["hot water, hair dryer, rubbing with snow","a warm object directly on the skin"]},{id:"topil",group:"B",tile:"Near drowning",title:"Near drowning",img:"/prva-pomoc/topil-bok.webp",imgCap:"on the side, head lower, clear the mouth",fotky:[{src:"/prva-pomoc/03-commons-figurina-na-boku-plaz.webp",cap:"rescue dummy on its side (CC0)"},{src:"/prva-pomoc/04-flickr-stena-zabalene-v-uteraku.webp",cap:"wrapped in a towel (CC BY-SA, Clevergrrl)"}],kroky:["Do not go onto the ice after him.","Lay him on his side, head lower than the body, clear the mouth. Only a few seconds.","Not breathing: card NOT BREATHING, start with breaths.","Dry him and wrap him.","To the vet, even if he looks fine."],extra:[{h:"Then watch his breathing for 2 days.",t:"Coughing, fast or heavy breathing = straight to the vet.",warn:!0},{h:"Also watch out for",t:"drinking a lot of water while fetching from water, and sea water. Staggering, vomiting, bloated belly = vet."}],nikdy:['do not press his belly to "get the water out"',"do not hold him head down for long"]},{id:"zlomenina",group:"C",tile:"Fracture",title:"Fracture, will not put weight on a leg",img:"/prva-pomoc/zlomenina-maly.webp",imgCap:"carry a small dog, the injured leg hangs free",fotky:[{src:"/prva-pomoc/mwd-nosidla-dvaja-nosici-2025.webp",cap:"stretcher (US Air Force, PD)"}],dalsi:[{img:"/prva-pomoc/zlomenina-deka.webp",h:"Large dog",t:"onto a jacket or blanket, pull it taut like a stretcher, two people carry."}],spoznas:["holds the leg up, it hangs at an odd angle, swells","with a spine injury drags the hind legs"],kroky:["Careful, even your own dog may bite you from pain. See card MUZZLE.","Do not straighten or splint the leg.","Just cover an open wound with a clean cloth.","Do not let him walk. Carry a small dog in your arms, the injured leg free, nothing pressing on it. Move a large dog onto a jacket or blanket and carry him with two people.","Suspected spine injury: only on something firm and flat (board, sleeping mat), without bending.","To the vet right away."],nikdy:["human painkillers. Ibuprofen and paracetamol poison dogs."],bezSignalu:"if he has to walk on his own, slowly and on three legs. Below the elbow or knee you can lightly pad the leg with a rolled sleeping mat. Never the thigh or the upper arm."},{id:"labka",group:"C",tile:"Paw",title:"Injured paw",img:"/prva-pomoc/labka-obvaz.webp",imgCap:"bandage from the toes up, two fingers under the bandage",vet:{h:"Straight to the vet if",items:["still bleeding after 15 minutes","the wound is deep or something is left in it","a claw is torn off","burned paws (hot asphalt: cool with cold water for 10 to 20 minutes)"]},kroky:["Rinse with clean water. Remove glass or a thorn only if it comes out easily. Leave deep ones.","Press with a clean cloth for 5 to 10 minutes.","Bandage: gauze on the wound, a bit of cotton wool between the toes, bandage from the toes upward. Two fingers must fit under the bandage.","Outdoors pull a bag or a sock over it, take it off at home.","Do not let him chew the bandage."],extra:[{h:"Grass awn between the toes",t:"pull out only what clearly sticks out. Swelling between the toes = vet, the awn travels deeper."}]},{id:"pohryzol",group:"C",tile:"Bite wound",title:"Bitten by a dog or a wild boar",img:"/prva-pomoc/pohryzenie-hrudnik.webp",imgCap:"chest wound: plastic and a palm",fotky:[{src:"/prva-pomoc/k9-tccc-osetrenie-simulator-2026.webp",cap:"bandaging a dog, simulator (US Army, PD)"}],vet:{h:"To the vet",items:["chest, belly, neck, head = right away","Everything else the same day, ideally within 6 hours"]},lead:["A small hole is deceptive. Teeth tear under the skin. The dog may look fine and collapse an hour later."],kroky:["Heavy bleeding: card HEAVY BLEEDING.","Rinse a small wound with clean water.","A chest wound that hisses or bubbles: cover it with plastic wrap or a bag and press. If breathing gets worse, lift one edge.","Do not push protruding intestines back. Cover them with a damp clean cloth.","Wrap him, do not let him walk, and go."],extra:[{h:"Fox or another wild animal",t:"call the vet because of rabies and have the vaccination record with you."}],nikdy:["peroxide in the wound","do not stitch or glue anything"]},{id:"popalenina",group:"C",tile:"Burn",title:"Burn",img:"/prva-pomoc/popalenina-chladenie.webp",imgCap:"cool water only on the burned spot",kroky:["Electricity: switch off the power first, only then touch the dog.","Cool with cool running water for 20 minutes. Cool a small dog only on the spot and keep the rest warm. Water not on the muzzle.","Chemical: wash off with plenty of water.","Cover loosely with cling film or a clean damp cloth.","Always to the vet. After biting through a cable even if he looks fine."],nikdy:["ice","ointment, butter, cream","do not pop blisters"]},{id:"oko",group:"C",tile:"Eye",title:"Injured eye",img:"/prva-pomoc/oko-vyplach.webp",imgCap:"a gentle stream from the inner corner",kroky:["Chemical: rinse at once and for long, 15 to 20 minutes. With saline if you have it, otherwise clean water. A gentle stream, not into the mouth.","Do not let him scratch the eye.","Do not remove a stuck object.","Eye popped out (flat-faced dogs): do not push it back. Cover it with a wet clean cloth, keep it moist and go right away.","To the vet the same day, even if he only squints."],nikdy:["do not press on the eye","no human eye drops"]},{id:"vracia",group:"C",tile:"Vomiting",title:"Vomiting, diarrhoea",img:"/prva-pomoc/vracia-koza.webp",imgCap:"skin between the shoulder blades should drop back at once",fotky:[{src:"/prva-pomoc/02-usmc-dasna-tlak-palcom.webp",cap:"checking the gums (USMC, PD)"},{src:"/prva-pomoc/04-usmc-voda-po-troche-z-dlani.webp",cap:"water a little at a time (USMC, PD)"}],vet:{h:"Straight to the vet if",items:["blood in the vomit or stool","retches with nothing coming up and has a bloated belly (card BLOATED BELLY)","keeps vomiting for more than 4 to 6 hours","is listless","is a puppy or an old dog"]},lead:["Watching is enough: vomited once, otherwise lively. Give water a little at a time and let him rest."],extra:[{h:"Is he dehydrated?",t:"Lift the skin between the shoulder blades. If it goes back slowly and the gums are dry and sticky, he needs a vet. In wrinkly and old dogs look at the gums instead."}],nikdy:["human medicines"]},{id:"nahubok",group:"D",tile:"Muzzle",title:"Muzzle from a bandage or a leash",img:"/prva-pomoc/nahubok-fazy.webp",imgCap:"loop from above, cross under the chin, bow behind the ears",fotky:[{src:"/prva-pomoc/mwd-improvizovany-nahubok-z-gazy.webp",cap:"gauze muzzle (US Army, PD)"}],kroky:["Make a loop, put it over the muzzle from above and pull it tight.","Cross the ends under the chin.","Tie them in a bow behind the ears, so it can come off at once."],extra:[{h:"Not if he",items:["is vomiting","breathes heavily","is choking","has a short nose","has an injured face or chest","is unconscious","is overheated"],after:"Wrap a flat-faced dog in a blanket instead.",warn:!0}]},{id:"poriadok",group:"D",tile:"Is he OK?",title:"Is he OK?",sub:"vital signs",img:"/prva-pomoc/dasna-tlak.webp",imgCap:"press on the pink gum above the canine",fotky:[{src:"/prva-pomoc/B1-dvids-femoralny-pulz-stojaci-pes.webp",cap:"pulse on the thigh (US Air Force, PD)"},{src:"/prva-pomoc/B2-dvids-femoralny-pulz-zozadu.webp",cap:"pulse on the thigh from behind (US Army, PD)"}],dalsi:[{img:"/prva-pomoc/tep-stehno.webp",h:"Pulse inside the thigh",t:"with the pads of the index and middle finger, high up near the groin."}],fakty:[{h:"Gums",t:"pink and moist. Pale = bleeding, shock. Blue = choking. Brick red = overheating. Yellow = liver, blood."},{h:"Press on the gum",t:"the pink should come back within 2 seconds. With dark gums press on a pink spot."},{h:"Breathing at rest",t:"10 to 35 per minute."},{h:"Pulse (left side behind the elbow or inside the thigh)",t:"feel with the index and middle finger, not the thumb. Large dog 60 to 100, small 90 to 140."},{h:"Temperature",t:"37.5 to 39.2 °C."}]},{id:"niest",group:"D",tile:"How to carry",title:"How to carry him",img:"/prva-pomoc/zlomenina-maly.webp",imgCap:"a small dog in your arms, chest and hindquarters",fotky:[{src:"/prva-pomoc/mwd-pes-na-nosidlach-2025.webp",cap:"dog on a stretcher (US Air Force, PD)"},{src:"/prva-pomoc/dvids-psia-figurina-na-boku-dvihaju-nosidla.webp",cap:"two lifting at once (US Navy, PD)"}],dalsi:[{img:"/prva-pomoc/zlomenina-deka.webp",h:"Large",t:"pull the blanket taut like a stretcher, two people carry."},{img:"/prva-pomoc/niest-doska.webp",h:"Spine",t:"firm board, pad the neck and sides, strap him on, lift together."}],fakty:[{h:"Small",t:"in your arms, support the chest and hindquarters."},{h:"Large",t:"on a jacket or blanket, two people."},{h:"Spine",t:"only on something firm."}]},{id:"lekarnicka",group:"D",tile:"First aid kit",title:"First aid kit for the backpack",img:"/prva-pomoc/lekarnicka.webp",imgCap:"10 things for the backpack",fotky:[{src:"/prva-pomoc/lekarnicka-pre-psa-box.webp",cap:"first aid kit for dogs (CC BY-SA, Elgaard)"},{src:"/prva-pomoc/commons-hacik-na-klieste-otom.webp",cap:"tick hook (CC BY-SA, Otom)"}],zoznam:["Gauze and bandage","self-adhesive bandage","tape","gloves","blunt-tipped scissors","tweezers and a tick hook","saline","emergency blanket","spare leash (muzzle and stretcher too)","number of your vet and the emergency vet"],extra:[{h:"Plus, agreed with your vet",t:"an allergy medicine with the dose for your dog."},{h:"Does not belong in the kit",t:"peroxide, activated charcoal, tourniquet, ointments."}]}],i=[[/card NOT BREATHING/g,"nedycha"],[/card HEAVY BLEEDING/g,"krvaca"],[/card MUZZLE/g,"nahubok"],[/card BLOATED BELLY/g,"brucho"]],r=[{id:"nedycha",group:"A",tile:"Nedýchá",title:"Nedýchá, nereaguje",sub:"oživování",img:"/prva-pomoc/nedycha-kpr.webp",imgCap:"stlačování hrudníku, zachránce u zad",fotky:[{src:"/prva-pomoc/commons-forthood-dalmatin-na-boku-kpr.webp",cap:"KPR na boku (US Army, PD)"},{src:"/prva-pomoc/dvids9092345-malinois-na-boku-dlane-na-hrudniku.webp",cap:"dlaně na hrudníku (US Army, PD)"}],spoznas:["nereaguje na jméno ani na dotek","hrudník se nehýbe","necítíš tep na levém boku za loktem"],kroky:["Zavolej na něj a zatřes s ním. Pokud se brání nebo dýchá, oživování nedělej.","Otevři tlamu, vytáhni jazyk, podívej se do krku. Co vidíš, vyndej.","Polož ho na bok na tvrdou zem.","Stlačuj hrudník: rychle, 2 stlačení za sekundu, do třetiny hloubky hrudníku. Vždy ho nech vrátit.","Po 30 stlačeních zavři tlamu, natáhni krk a 2× mu vdechni do nosu, až se zvedne hrudník.","Opakuj 30 : 2. Každé 2 minuty na pár sekund zkontroluj dech. Pokud jste dva, střídejte se.","Pokračuj i cestou k veterináři."],extra:[{h:"Kam dát ruce",items:["Střední a velký pes s kulatým hrudníkem (labrador): obě dlaně na nejširší místo hrudníku.","Úzký hluboký hrudník (chrt, dobrman): obě dlaně nad srdce, tam, kde se hrudníku dotkne loket.","Malý pes do 10 kg: jedna ruka obemkne hrudník, stlačuješ palcem proti prstům.","Buldok, mops: na boku, dlaně na nejširší místo."]}],nikdy:["nestlačuj psa, kterému bije srdce","nepřerušuj stlačování na víc než 10 sekund"],bezSignalu:"oživování jen kupuje čas na cestu. Upřímně: přežije málo psů (5 až 7 ze 100 i na klinice). Pokud je pomoc daleko a nic se nemění, smíš přestat."},{id:"dusi",group:"A",tile:"Dusí se",title:"Dusí se",img:"/prva-pomoc/dusi-heimlich.webp",imgCap:"pěst hned za poslední žebra",spoznas:["panika, škrábe se na tlamě","nemůže se nadechnout, je potichu","dásně modrají"],lead:["Pokud kašle, vzduch prochází. Nech ho kašlat a jeď k veterináři."],kroky:["Otevři tlamu a podívej se. Co vidíš, vyndej pinzetou nebo kleštěmi. Ne prsty.","Nejde to: postav se za psa, pěst pod žebra, 5 prudkých stlačení dovnitř a nahoru. Malého psa drž zády k sobě.","Pořád nic: zvedni mu zadek, hlava dolů, 5 úderů dlaní mezi lopatky. Opakuj.","Ztratil vědomí: teď už vyndej prsty, co je v krku.","Míček v krku a pes v bezvědomí: polož ho na záda, natáhni krk, palci zvenku pod čelistí tlač míček směrem k tlamě.","Nedýchá: pokračuj kartou NEDÝCHÁ.","I když předmět vyšel, jeď k veterináři. Krk může otéct."],nikdy:["prsty do tlamy psa při vědomí","nehmatej naslepo","žádný náhubek"],bezSignalu:"celý kruh opakuj sám, dokud předmět nevyjde."},{id:"krvaca",group:"A",tile:"Silně krvácí",title:"Silně krvácí",img:"/prva-pomoc/krvaca-tlak.webp",imgCap:"tlak přímo na ránu, celou dlaní",fotky:[{src:"/prva-pomoc/dvids9049537-tlak-dlanami-cez-gazu-figurina.webp",cap:"tlak dlaněmi přes gázu (US Air Force, PD)"},{src:"/prva-pomoc/commons-tccc-obvaz-prednej-nohy-figurina.webp",cap:"tlakový obvaz nohy (US Army, PD)"}],spoznas:["krev stříká nebo rychle teče","bledé dásně, rychlý dech, studené tlapky = šok"],kroky:["Přitiskni na ránu čistou látku (tričko, šátek) a drž. Silně, celou dlaní.","Nohu zvedni nad úroveň srdce, pokud to jde.","Obvaž pevně přes látku.","Prosáklo to? Nic nesundávej. Přidej další vrstvu a tlač dál.","Jeď k veterináři, tlak drž celou cestu."],posledne:{img:"/prva-pomoc/krvaca-skrtidlo.webp",h:"Až když nic jiného nepomáhá: škrtidlo",t:"široký pruh látky NAD ránou, pevně uvázat. Zapiš si čas a už ho nepovoluj."},extra:[{h:"Zapíchnutý předmět (větev, sklo)",t:"nevytahuj. Obvaž kolem něj."},{h:"Dráp, ucho, tlapka",t:"krvácejí hodně, vypadají hůř, než jsou. Tlač 5 až 10 minut bez dívání. Pokud nepřestane do 15 minut, pohotovost."}],nikdy:["nekoukej pod obvaz, jestli to přestalo","žádný peroxid ani alkohol do rány"],bezSignalu:"škrtidlo je poslední možnost, jen na nohu nebo ocas, když tlak nezabírá. Použij široký elastický obvaz, zapiš si čas a už ho nepovoluj."},{id:"brucho",group:"A",tile:"Nafouknuté břicho",title:"Nafouknuté břicho, dáví naprázdno",sub:"otočení žaludku",img:"/prva-pomoc/brucho-nafuknute.webp",imgCap:"nafouknutý žaludek tlačí na žebra",spoznas:["chce zvracet a nic nevyjde","břicho tvrdé jako buben","nemůže si lehnout, slintá","hlavně velcí psi s hlubokým hrudníkem"],kroky:["Hned do auta k NEJBLIŽŠÍMU veterináři. Zavolej mu cestou.","Nedávej nic jíst ani pít.","Zkolabuje: karta NEDÝCHÁ."],extra:[{h:"Doma se nedá udělat nic.",t:"Bez operace pes zemře, po 6 hodinách šance rychle klesají.",warn:!0}],nikdy:["nečekej, jestli to přejde","žádné kapky proti nadýmání","nic nepropichuj"]},{id:"krce",group:"A",tile:"Záchvat",title:"Záchvat, křeče",img:"/prva-pomoc/krce-cas.webp",imgCap:"nedrž ho, měř čas",vet:{h:"Hned k veterináři, pokud",items:["záchvat trvá víc než 2 minuty (volej)","víc než 5 minut (jde o život)","druhý záchvat ten samý den","neprobral se","je to jeho první záchvat (ozvi se ten den)"]},spoznas:["upadne, ztuhne, „pádluje“ nohama, slintá, může se pomočit","potom je zmatený"],kroky:["Podívej se na hodinky. Měř čas.","Odklid všechno, o co se může uhodit. Nedrž ho.","Ticho, stín. Nepřikrývej ho, přehřívá se.","Pokud to jde, natoč video pro veterináře.","Po záchvatu: klid, voda, pozor na schody a svah. Může být zmatený až den."],nikdy:["ruce do tlamy (jazyk nespolkne, ale pokouše tě)","nedrž ho, nestříkej na něj vodu","nic mu nedávej do tlamy","nepřenášej ho během záchvatu"],bezSignalu:"počkej, až záchvat skončí, potom ho nes. V horku mu vlhči břicho a třísla."},{id:"prehriatie",group:"B",tile:"Přehřátí",title:"Přehřátí",img:"/prva-pomoc/prehriatie.webp",imgCap:"voda na hruď, břicho a stehna, hlava suchá",fotky:[{src:"/prva-pomoc/pes-vo-vode.webp",cap:"zdravý pes ve vodě (CC BY-SA, Chris Light)"}],spoznas:["silně oddychuje a nepřestává","slintá, zvrací, potácí se","v nejhorším křeče a kolaps"],kroky:["Stůj. Stín.","Chlaď HNED, nejstudenější vodou, jakou máš (potok, láhev, hadice). Nejdřív chladit, až potom cestovat.","Zdravého psa při vědomí ponoř do vody po krk. Hlava vždy nad vodou.","Starého, nemocného, krátkonosého nebo apatického psa neponořuj. Polévej ho a ovívej.","Lij na hruď, břicho a vnitřní stehna. Hlava a tlama zůstávají suché.","Dej mu pít po doušcích.","Přestaň, když se dech zklidní. Potom k veterináři, i když vypadá dobře."],nikdy:["nečekej s chlazením na veterináře","nepřikrývej ho mokrým ručníkem (pod něj ano)","nenuť ho jít pěšky"],bezSignalu:"chlazení JE léčba. Chlaď v potoce, potom ho pomalu nes."},{id:"had",group:"B",tile:"Had",title:"Uštkl ho had",sub:"zmije",img:"/prva-pomoc/had-nesenie.webp",imgCap:"malého psa nes, ať nechodí",fotky:[{src:"/prva-pomoc/vlastna-opuch-prednej-nohy-po-vretenici-1.webp",cap:"otok nohy po zmiji"},{src:"/prva-pomoc/vretenica-samica-pieniny.webp",cap:"zmije (CC BY-SA, Charles J. Sharp)",znak:"zle"},{src:"/prva-pomoc/uzovka-hlava-zlte-skvrny.webp",cap:"užovka (PD, G. Chernilevsky)",znak:"ok"}],porovnanie:{img:"/prva-pomoc/vretenica-vs-uzovka.webp",h:"Zmije, nebo užovka?",l:"Jedovatá",r:"Neškodná",t:"Zmije: klikatý pruh na hřbetě, svislá zornice. Užovka: žluté půlměsíce za hlavou, kulatá zornice. Hada stejně nechytej."},spoznas:["náhlá bolest a rychlý tmavý otok, často na tlamě nebo noze","někdy dvě tečky","slabost, potácení"],kroky:["Klid. Hada nechytej, stačí fotka z dálky.","Psa uklidni a nenech ho běhat. Pohyb roznáší jed.","Malého psa nes. K velkému přiveď auto, nebo jdi pomalu s přestávkami.","Zavolej veterináři, že jedete.","Jeď hned, i když otok nevidíš. Příznaky přijdou do hodiny."],nikdy:["škrtidlo ani obvaz","nevysávej, neřež","žádný led","žádné léky"],bezSignalu:"jediná první pomoc je klid a rychlý, klidný přesun."},{id:"hmyz",group:"B",tile:"Hmyz",title:"Bodl ho hmyz",img:"/prva-pomoc/hmyz-zihadlo.webp",imgCap:"žihadlo seškrábni do boku, nemačkej",fotky:[{src:"/prva-pomoc/osa-vespula.webp",cap:"vosa (CC BY-SA, Soebe)"}],vet:{h:"Hned k veterináři, pokud",items:["oteče tlama, hlava nebo krk","dýchá těžce, píská","zvrací nebo má průjem","slábne, kolabuje","bodnutí je v tlamě nebo v krku","bodnutí je hodně"]},spoznas:["kňučí, olizuje si místo, malý otok"],kroky:["Žihadlo vyndej hned, čímkoli (nehet, karta, pinzeta). Rozhoduje rychlost. Nemačkej váček.","Přilož studený obklad přes látku, 10 minut.","Sleduj ho aspoň půl hodiny, potom ještě zbytek dne."],nikdy:["lidské léky na alergii bez pokynu veterináře. Některé obsahují látky, které psa otráví."],bezSignalu:"pokud chodíš daleko od cest, vyžádej si předem od svého veterináře lék a dávku pro svého psa."},{id:"jed",group:"B",tile:"Jed",title:"Snědl jed",img:"/prva-pomoc/jed-vybrat.webp",imgCap:"úchop za špičáky, vyndej zepředu, vyfoť obal",dalsi:[{img:"/prva-pomoc/jed-panel.webp",h:"Vždy nebezpečné"}],spoznas:["zvrací, slintá, třese se, potácí se","někdy nic, příznaky přijdou za hodiny až dny"],kroky:["Vezmi mu to. Vyprázdni tlamu, pokud to jde bezpečně.","Zjisti co, kolik a kdy. Vyfoť obal nebo vezmi vzorek.","Volej veterináře HNED. Nečekej na příznaky.","Jeď, i když vypadá zdravě."],extra:[{h:"Vždy nebezpečné",items:["čokoláda (čím tmavší, tím horší)","sladidlo xylitol (žvýkačky)","hrozny a rozinky","jed na potkany a slimáky","nemrznoucí směs","lidské léky (ibuprofen, paracetamol)","houby","zelená voda se sinicemi"],pills:!0},{h:"Sinice",t:"opláchni ho čistou vodou a nedovol mu olizovat srst."}],nikdy:["nevyvolávej zvracení, pokud ti to veterinář výslovně neřekne.","žádná slaná voda","žádné mléko ani živočišné uhlí místo veterináře"],bezSignalu:"neztrácej čas domácími recepty. Jdi k signálu a k autu."},{id:"kliest",group:"B",tile:"Klíště",title:"Klíště",img:"/prva-pomoc/kliest-pinzeta.webp",imgCap:"pinzetou těsně u kůže, rovně nahoru",fotky:[{src:"/prva-pomoc/ixodes-ricinus-samica-samec.webp",cap:"klíště obecné (CC BY-SA, Alan R Walker)"}],vet:{h:"Hned k veterináři, pokud",pre:"3 týdny sleduj.",items:["je apatický, nežere, má horečku","moč je tmavá nebo červená","žloutnou mu dásně nebo oči"],post:"Na Slovensku i v Česku je to často babezióza a jde o dny."},kroky:["Vyndej ho hned, nečekej, až budeš doma.","Chyť ho těsně u kůže.","Pinzetou táhni rovně a pomalu. Háčkem na klíšťata otáčej.","Nemačkej mu tělo.","Místo umyj. Zapiš si datum.","Prohlédni celého psa: hlava, uši, podpaží, mezi prsty, třísla."],nikdy:["olej, alkohol, lak ani oheň na klíště"]},{id:"podchladenie",group:"B",tile:"Podchlazení",title:"Podchlazení",img:"/prva-pomoc/podchladenie.webp",imgCap:"izolace pod psa, zabalit, teplá láhev u hrudi",fotky:[{src:"/prva-pomoc/pes-zabaleny-v-deke.webp",cap:"pes zabalený v dece (CC0)"}],spoznas:["třese se, je ztuhlý, zpomalený","když se třást přestane a slábne, je to horší, ne lepší"],kroky:["Závětří, sucho. Sundej mokrý postroj.","Osuš ho a polož na něco, co izoluje (karimatka, batoh).","Zabal ho, i zespodu. Přitiskni si ho k tělu.","Láhev s teplou vodou zabal do látky a dej mu ji k hrudníku a břichu.","Pokud pije, dej vlažnou vodu.","K veterináři, i když se probere."],extra:[{h:"Omrzliny (uši, ocas, tlapky jsou bledé, tvrdé)",t:"netřít. Ohřívat až tam, kde už znovu nezmrznou, teplou vodou, ve které udržíš ruku."}],nikdy:["horká voda, fén, tření sněhem","teplý předmět přímo na kůži"]},{id:"topil",group:"B",tile:"Topil se",title:"Topil se",img:"/prva-pomoc/topil-bok.webp",imgCap:"na boku, hlava níž, vyčisti tlamu",fotky:[{src:"/prva-pomoc/03-commons-figurina-na-boku-plaz.webp",cap:"záchranářská figurína na boku (CC0)"},{src:"/prva-pomoc/04-flickr-stena-zabalene-v-uteraku.webp",cap:"zabalený v ručníku (CC BY-SA, Clevergrrl)"}],kroky:["Na led za ním nechoď.","Polož ho na bok, hlavu níž než tělo, vyčisti tlamu. Jen pár sekund.","Nedýchá: karta NEDÝCHÁ, začni vdechy.","Osuš ho a zabal.","K veterináři, i když vypadá dobře."],extra:[{h:"Potom 2 dny sleduj dech.",t:"Kašel, rychlé nebo těžké dýchání = hned k veterináři.",warn:!0},{h:"Pozor i na",t:"hodně vypité vody při aportování z vody a mořskou vodu. Potácení, zvracení, nafouknuté břicho = veterinář."}],nikdy:["nestlačuj mu břicho, aby „vyšla voda“","nedrž ho dlouho hlavou dolů"]},{id:"zlomenina",group:"C",tile:"Zlomenina",title:"Zlomenina, nedošlápne na nohu",img:"/prva-pomoc/zlomenina-maly.webp",imgCap:"malého nes, zraněná noha volně",fotky:[{src:"/prva-pomoc/mwd-nosidla-dvaja-nosici-2025.webp",cap:"nosítka (US Air Force, PD)"}],dalsi:[{img:"/prva-pomoc/zlomenina-deka.webp",h:"Velký pes",t:"na bundu nebo deku, napnout jako nosítka, nesou dva."}],spoznas:["nohu drží nahoře, visí v divném úhlu, otéká","u páteře táhne zadní nohy"],kroky:["Pozor, i tvůj pes tě může bolestí pokousat. Viz kartu NÁHUBEK.","Nohu nenarovnávej a nedlahuj.","Otevřenou ránu jen překryj čistou látkou.","Nenech ho chodit. Malého nes v náručí, zraněná noha volně, nic ji netlačí. Velkého přesuň na bundu nebo deku a neste ho dva.","Podezření na páteř: jen na něčem pevném a rovném (prkno, karimatka), bez ohýbání.","K veterináři hned."],nikdy:["lidské léky proti bolesti. Ibuprofen a paracetamol psa otráví."],bezSignalu:"pokud musí jít sám, tak pomalu a po třech. Nohu pod loktem nebo kolenem můžeš zlehka obložit srolovanou karimatkou. Stehno a rameno nikdy."},{id:"labka",group:"C",tile:"Tlapka",title:"Poraněná tlapka",img:"/prva-pomoc/labka-obvaz.webp",imgCap:"obvaz od prstů nahoru, dva prsty pod obvaz",vet:{h:"Hned k veterináři, pokud",items:["krvácí i po 15 minutách","rána je hluboká nebo v ní něco zůstalo","je utržený dráp","popálil si tlapky (horký asfalt: chlaď studenou vodou 10 až 20 minut)"]},kroky:["Opláchni čistou vodou. Sklo nebo trn vyndej, jen pokud jde lehce. Hluboké nech.","Tlač čistou látkou 5 až 10 minut.","Obvaž: gáza na ránu, kousek vaty mezi prsty, obvaz od prstů nahoru. Pod obvaz se musí vejít dva prsty.","Venku na něj natáhni sáček nebo ponožku, doma sundej.","Nenech ho obvaz kousat."],extra:[{h:"Osina mezi prsty",t:"vytáhni jen to, co jasně trčí. Otok mezi prsty = veterinář, osina putuje hlouběji."}]},{id:"pohryzol",group:"C",tile:"Pokousání",title:"Pokousal ho pes nebo divočák",img:"/prva-pomoc/pohryzenie-hrudnik.webp",imgCap:"rána na hrudníku: fólie a dlaň",fotky:[{src:"/prva-pomoc/k9-tccc-osetrenie-simulator-2026.webp",cap:"obvazování psa, simulátor (US Army, PD)"}],vet:{h:"K veterináři",items:["hrudník, břicho, krk, hlava = hned","Všechno ostatní ten samý den, nejlépe do 6 hodin"]},lead:["Malá dírka klame. Zuby trhají pod kůží. Pes může vypadat v pořádku a zkolabovat za hodinu."],kroky:["Silné krvácení: karta SILNĚ KRVÁCÍ.","Malou ránu vypláchni čistou vodou.","Rána na hrudníku, ze které to syčí nebo bublá: překryj ji fólií nebo sáčkem a přitiskni. Pokud se dech zhorší, okraj nadzvedni.","Vyhřezlá střeva netlač zpátky. Překryj je vlhkou čistou látkou.","Zabal ho, ať nechodí, a jeď."],extra:[{h:"Liška nebo jiné divoké zvíře",t:"zavolej veterináři kvůli vzteklině a měj u sebe očkovací průkaz."}],nikdy:["peroxid do rány","nic nezašívej ani nelep"]},{id:"popalenina",group:"C",tile:"Popálenina",title:"Popálenina",img:"/prva-pomoc/popalenina-chladenie.webp",imgCap:"chladná voda jen na popálené místo",kroky:["Elektřina: nejdřív vypni proud, až potom se psa dotkni.","Chlaď chladnou tekoucí vodou 20 minut. Malého psa chlaď jen na místě a zbytek drž v teple. Vodu ne na tlamu.","Chemikálie: smývej velkým množstvím vody.","Volně překryj potravinovou fólií nebo čistou vlhkou látkou.","K veterináři vždy. Po překousnutém kabelu i tehdy, když vypadá dobře."],nikdy:["led","mast, máslo, krém","nepropichuj puchýře"]},{id:"oko",group:"C",tile:"Oko",title:"Poraněné oko",img:"/prva-pomoc/oko-vyplach.webp",imgCap:"slabý proud od vnitřního koutku",kroky:["Chemikálie: vyplachuj hned a dlouho, 15 až 20 minut. Čím máš: fyziologický roztok, jinak čistá voda. Slabým proudem, ne do tlamy.","Nenech ho škrábat se na oku.","Zapíchnutý předmět nevyndávej.","Vypadlé oko (krátkonosí psi): nezatlačuj. Překryj mokrou čistou látkou, stále vlhči a jeď hned.","K veterináři ten samý den, i když jen mžourá."],nikdy:["netlač na oko","žádné lidské kapky"]},{id:"vracia",group:"C",tile:"Zvrací",title:"Zvrací, má průjem",img:"/prva-pomoc/vracia-koza.webp",imgCap:"kůže mezi lopatkami má hned klesnout",fotky:[{src:"/prva-pomoc/02-usmc-dasna-tlak-palcom.webp",cap:"kontrola dásní (USMC, PD)"},{src:"/prva-pomoc/04-usmc-voda-po-troche-z-dlani.webp",cap:"voda po troškách (USMC, PD)"}],vet:{h:"Hned k veterináři, pokud",items:["krev ve zvratcích nebo stolici","dáví naprázdno a má nafouknuté břicho (karta NAFOUKNUTÉ BŘICHO)","zvrací opakovaně víc než 4 až 6 hodin","je apatický","je to štěně nebo starý pes"]},lead:["Stačí sledovat: jednou zvracel, jinak je čilý. Dávej vodu po troškách a nech ho odpočívat."],extra:[{h:"Je dehydratovaný?",t:"Zvedni kůži mezi lopatkami. Pokud se vrací pomalu a dásně jsou suché a lepkavé, potřebuje veterináře. U vrásčitých a starých psů se radši podívej na dásně."}],nikdy:["lidské léky"]},{id:"nahubok",group:"D",tile:"Náhubek",title:"Náhubek z obvazu nebo vodítka",img:"/prva-pomoc/nahubok-fazy.webp",imgCap:"smyčka shora, křížení pod bradou, mašle za ušima",fotky:[{src:"/prva-pomoc/mwd-improvizovany-nahubok-z-gazy.webp",cap:"náhubek z gázy (US Army, PD)"}],kroky:["Udělej smyčku, shora ji nasaď na tlamu a utáhni.","Překřiž konce pod bradou.","Zavaž na mašli za ušima, aby šel hned sundat."],extra:[{h:"Ne, pokud",items:["zvrací","dýchá těžce","dusí se","má krátký nos","má poraněnou tvář nebo hrudník","je v bezvědomí","je přehřátý"],after:"Krátkonosého psa radši zabal do deky.",warn:!0}]},{id:"poriadok",group:"D",tile:"Je v pořádku?",title:"Je v pořádku?",sub:"životní funkce",img:"/prva-pomoc/dasna-tlak.webp",imgCap:"zatlač na růžovou dáseň nad špičákem",fotky:[{src:"/prva-pomoc/B1-dvids-femoralny-pulz-stojaci-pes.webp",cap:"tep na stehně (US Air Force, PD)"},{src:"/prva-pomoc/B2-dvids-femoralny-pulz-zozadu.webp",cap:"tep na stehně zezadu (US Army, PD)"}],dalsi:[{img:"/prva-pomoc/tep-stehno.webp",h:"Tep uvnitř stehna",t:"bříšky ukazováčku a prostředníčku, vysoko u třísel."}],fakty:[{h:"Dásně",t:"růžové a vlhké. Bledé = krvácení, šok. Modré = dusí se. Cihlově červené = přehřátí. Žluté = játra, krev."},{h:"Zatlač na dáseň",t:"růžová se má vrátit do 2 sekund. U tmavých dásní tlač na růžové místo."},{h:"Dech v klidu",t:"10 až 35 za minutu."},{h:"Tep (levý bok za loktem nebo vnitřek stehna)",t:"hmatej ukazováčkem a prostředníčkem, ne palcem. Velký pes 60 až 100, malý 90 až 140."},{h:"Teplota",t:"37,5 až 39,2 °C."}]},{id:"niest",group:"D",tile:"Jak ho nést",title:"Jak ho nést",img:"/prva-pomoc/zlomenina-maly.webp",imgCap:"malého v náručí, hrudník a zadek",fotky:[{src:"/prva-pomoc/mwd-pes-na-nosidlach-2025.webp",cap:"pes na nosítkách (US Air Force, PD)"},{src:"/prva-pomoc/dvids-psia-figurina-na-boku-dvihaju-nosidla.webp",cap:"dva zvedají naráz (US Navy, PD)"}],dalsi:[{img:"/prva-pomoc/zlomenina-deka.webp",h:"Velký",t:"deku napni jako nosítka, nesou dva."},{img:"/prva-pomoc/niest-doska.webp",h:"Páteř",t:"pevné prkno, podlož krk a boky, připoutej, zvedejte naráz."}],fakty:[{h:"Malý",t:"v náručí, podepři hrudník a zadek."},{h:"Velký",t:"na bundě nebo dece, dva."},{h:"Páteř",t:"jen na pevném."}]},{id:"lekarnicka",group:"D",tile:"Lékárnička",title:"Lékárnička do batohu",img:"/prva-pomoc/lekarnicka.webp",imgCap:"10 věcí do batohu",fotky:[{src:"/prva-pomoc/lekarnicka-pre-psa-box.webp",cap:"lékárnička pro psa (CC BY-SA, Elgaard)"},{src:"/prva-pomoc/commons-hacik-na-klieste-otom.webp",cap:"háček na klíšťata (CC BY-SA, Otom)"}],zoznam:["Gáza a obvaz","samolepicí obvaz","páska","rukavice","nůžky s tupou špičkou","pinzeta a háček na klíšťata","fyziologický roztok","záchranná fólie","náhradní vodítko (náhubek i nosítka)","číslo na veterináře a pohotovost"],extra:[{h:"K tomu po dohodě s veterinářem",t:"lék na alergii s dávkou pro tvého psa."},{h:"Do lékárničky nepatří",t:"peroxid, živočišné uhlí, škrtidlo, masti."}]}],s=[[/kartou NEDÝCHÁ|karta NEDÝCHÁ/g,"nedycha"],[/karta SILNĚ KRVÁCÍ/g,"krvaca"],[/kartu NÁHUBEK/g,"nahubok"],[/karta NAFOUKNUTÉ BŘICHO/g,"brucho"]],e={sk:{cards:o,links:t},en:{cards:n,links:i},cs:{cards:r,links:s}};function p(a){return e[a]??e.en}const l=["A","B","C","D"],h={had:"had",kliest:"den-tick",poriadok:"zdravie"},d="sos-pomoc";export{l as AID_GROUPS,h as AID_ICON,d as AID_ICON_DEFAULT,p as aidContent};
